            w = test_w;
            #10; // Wait for combinational propagation

            if (Y1 !== exp_Y1) begin
                $display("Mismatch: y=6'b%b, w=%b | Expected Y1=%b, Got Y1=%b", test_y, test_w, exp_Y1, Y1);
                errors = errors + 1;
            end
            if (Y3 !== exp_Y3) begin
                $display("Mismatch: y=6'b%b, w=%b | Expected Y3=%b, Got Y3=%b", test_y, test_w, exp_Y3, Y3);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking
    initial begin
        // Initialize inputs
        y = 6'b000000;
        w = 1'b0;
        #10;

        // FSM Transitions Analysis:
        // State encodings:
        // A = 6'b000001 (y[0])
        // B = 6'b000010 (y[1])
        // C = 6'b000100 (y[2])
        // D = 6'b001000 (y[3])
        // E = 6'b010000 (y[4])
        // F = 6'b100000 (y[5])

        // Next State Logic Analysis (finding incoming paths for state B / y[1] and state D / y[3]):
        // State B (y[1]) is entered from:
        // - A when w=1 (y[0] & w)
        // State D (y[3]) is entered from:
        // - B when w=0 (y[1] & ~w)
        // - C when w=0 (y[2] & ~w)
        // - E when w=0 (y[4] & ~w)
        // - F when w=0 (y[5] & ~w)

        // Let's test all states with w = 0 and w = 1

        // --- State A (y[0] = 6'b000001) ---
        // w=0 -> A (Next: A) -> B not entered, D not entered -> Y1=0, Y3=0
        check_outputs(6'b000001, 1'b0, 1'b0, 1'b0);
        // w=1 -> B (Next: B) -> B entered from A, D not entered -> Y1=1, Y3=0
        check_outputs(6'b000001, 1'b1, 1'b1, 1'b0);

        // --- State B (y[1] = 6'b000010) ---
        // w=0 -> D (Next: D) -> B not entered, D entered from B -> Y1=0, Y3=1
        check_outputs(6'b000010, 1'b0, 1'b0, 1'b1);
        // w=1 -> C (Next: C) -> B not entered, D not entered -> Y1=0, Y3=0
        check_outputs(6'b000010, 1'b1, 1'b0, 1'b0);

        // --- State C (y[2] = 6'b000100) ---
        // w=0 -> D (Next: D) -> B not entered, D entered from C -> Y1=0, Y3=1
        check_outputs(6'b000100, 1'b0, 1'b0, 1'b1);
        // w=1 -> E (Next: E) -> B not entered, D not entered -> Y1=0, Y3=0
        check_outputs(6'b000100, 1'b1, 1'b0, 1'b0);

        // --- State D (y[3] = 6'b001000) ---
        // w=0 -> A (Next: A) -> B not entered, D not entered -> Y1=0, Y3=0
        check_outputs(6'b001000, 1'b0, 1'b0, 1'b0);
        // w=1 -> F (Next: F) -> B not entered, D not entered -> Y1=0, Y3=0
        check_outputs(6'b001000, 1'b1, 1'b0, 1'b0);

        // --- State E (y[4] = 6'b010000) ---
        // w=0 -> D (Next: D) -> B not entered, D entered from E -> Y1=0, Y3=1
        check_outputs(6'b010000, 1'b0, 1'b0, 1'b1);
        // w=1 -> E (Next: E) -> B not entered, D not entered -> Y1=0, Y3=0
        check_outputs(6'b010000, 1'b1, 1'b0, 1'b0);

        // --- State F (y[5] = 6'b100000) ---
        // w=0 -> D (Next: D) -> B not entered, D entered from F -> Y1=0, Y3=1
        check_outputs(6'b100000, 1'b0, 1'b0, 1'b1);
        // w=1 -> C (Next: C) -> B not entered, D not entered -> Y1=0, Y3=0
        check_outputs(6'b100000, 1'b1, 1'b0, 1'b0);

        // --- Corner / Invalid One-Hot Cases ---
        // Zero state
        check_outputs(6'b000000, 1'b0, 1'b0, 1'b0);
        check_outputs(6'b000000, 1'b1, 1'b0, 1'b0);
        // Multi-hot state
        check_outputs(6'b000011, 1'b0, 1'b0, 1'b1);

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
